// Lo que el negocio espera de un transportista (nuestra interfaz): cotizar({ km, kg }) -> { ars, horas }
// Lo que ofrece un proveedor externo INVENTADO: otro idioma y otras unidades (gramos, centavos, minutos, todo como texto).
const ProveedorExterno = {
  price(gramos, kmTexto) {
    const km = Number(kmTexto);
    return { amt_cents: String(120000 + km * 8000 + Math.round(gramos * 1.5)), eta_min: String(km * 4) };
  },
};

// El adaptador: expone NUESTRA interfaz y traduce hacia la del proveedor (y la respuesta, de vuelta).
function adaptarProveedor(proveedor) {
  return {
    cotizar({ km, kg }) {
      const r = proveedor.price(kg * 1000, String(km));
      return { ars: Number(r.amt_cents) / 100, horas: Math.round((Number(r.eta_min) / 60) * 100) / 100 };
    },
  };
}

const transportista = adaptarProveedor(ProveedorExterno);
console.log(transportista.cotizar({ km: 10, kg: 12 }));
console.log('sin adaptador, el negocio vería:', ProveedorExterno.price(12000, '10'));

// Cuatro piezas del depósito, cada una con su propia interfaz (todo inventado).
const inventario = { reservar(sku, n) { return n <= 5 ? { ok: true } : { ok: false, motivo: 'sin stock' }; } };
const cotizador  = { precio(km, kg) { return 1200 + 80 * km + 15 * kg; } };
const asignador  = { elegir(kg) { return kg <= 15 ? 'moto' : 'camioneta'; } };
const remitos    = { _n: 0, emitir(datos) { return { remito: ++this._n, ...datos }; } };

// ANTES: cada pantalla o endpoint repetía esta coreografía, con su orden y sus casos de error.
function despacharAMano(pedido) {
  const r = inventario.reservar(pedido.sku, pedido.cantidad);
  if (!r.ok) return { error: r.motivo };
  const vehiculo = asignador.elegir(pedido.kg);
  const precio = cotizador.precio(pedido.km, pedido.kg);
  return remitos.emitir({ sku: pedido.sku, vehiculo, precio });
}

// DESPUÉS: la fachada es la única que conoce las cuatro piezas, y además unifica la forma de la respuesta.
const despachos = {
  despachar({ sku, cantidad, kg, km }) {
    const reserva = inventario.reservar(sku, cantidad);
    if (!reserva.ok) return { ok: false, motivo: reserva.motivo };
    const vehiculo = asignador.elegir(kg);
    const precio = cotizador.precio(km, kg);
    return { ok: true, ...remitos.emitir({ sku, vehiculo, precio }) };
  },
};

console.log('a mano  :', despacharAMano({ sku: 'A-100', cantidad: 2, kg: 12, km: 10 }));
console.log('fachada :', despachos.despachar({ sku: 'A-100', cantidad: 2, kg: 12, km: 10 }));
console.log('fachada :', despachos.despachar({ sku: 'A-100', cantidad: 9, kg: 12, km: 10 }));

// Interfaz común: cotizar(km) -> Promise<number>. El «real» es un proveedor inventado y flojo:
// falla la primera vez que se le pide cada distancia.
let llamadasReales = 0;
const vistos = new Set();
const real = {
  async cotizar(km) {
    llamadasReales++;
    if (!vistos.has(km)) { vistos.add(km); throw new Error('timeout'); }
    return 1200 + 80 * km;
  },
};

// Cada decorador recibe un cotizador y devuelve OTRO con la misma interfaz.
const conReintentos = (c, max = 3) => ({
  async cotizar(km) {
    for (let i = 1; ; i++) {
      try { return await c.cotizar(km); } catch (e) { if (i >= max) throw e; }
    }
  },
});
const conCache = (c) => {
  const guardado = new Map();
  return { async cotizar(km) { if (!guardado.has(km)) guardado.set(km, await c.cotizar(km)); return guardado.get(km); } };
};
const conRegistro = (c, nombre, log) => ({
  async cotizar(km) { log.push(`${nombre}: pide ${km} km`); return c.cotizar(km); },
});

async function probar(titulo, armar) {
  llamadasReales = 0; vistos.clear();
  const log = [];
  const c = armar(log);
  const r1 = await c.cotizar(10);
  const r2 = await c.cotizar(10);
  console.log(`${titulo}: resultados ${r1}, ${r2}; llamadas reales ${llamadasReales}; líneas de registro ${log.length}`);
}

// El orden de los envoltorios no cambia el resultado, pero sí lo que se cuenta y lo que se ahorra:
await probar('A) registro(reintentos(real))        ', (log) => conRegistro(conReintentos(real), 'R', log));
await probar('B) reintentos(registro(real))        ', (log) => conReintentos(conRegistro(real, 'R', log)));
await probar('C) registro(cache(reintentos(real))) ', (log) => conRegistro(conCache(conReintentos(real)), 'R', log));

// Un depósito real (inventado) y un proxy que le exige rol antes de cada operación.
const deposito = {
  consultar(sku) { return `stock de ${sku}: 40`; },
  ajustar(sku, n) { return `stock de ${sku} ajustado en ${n}`; },
};
function conPermisos(objetivo, rol, permitido) {
  return new Proxy(objetivo, {
    get(obj, nombre) {
      const f = obj[nombre];
      if (typeof f !== 'function') return f;
      return (...args) => {
        if (!permitido[rol]?.includes(nombre)) throw new Error(`rol «${rol}» no puede ${nombre}`);
        return f.apply(obj, args);
      };
    },
  });
}
const REGLAS = { operador: ['consultar'], supervisor: ['consultar', 'ajustar'] };
const comoOperador = conPermisos(deposito, 'operador', REGLAS);
console.log(comoOperador.consultar('A-100'));
console.log('¿es el mismo objeto que el depósito?', comoOperador === deposito);
try { comoOperador.ajustar('A-100', -5); } catch (e) { console.log(e.message); }

// Proxy virtual: el mapa de zonas pesado no se carga hasta que alguien lo usa.
function perezoso(cargar) {
  let valor;
  return new Proxy({}, {
    get(_, clave) { if (valor === undefined) { console.log('(cargando el mapa de zonas…)'); valor = cargar(); } return valor[clave]; },
  });
}
const zonas = perezoso(() => ({ 1000: 'Centro', 1425: 'Palermo' }));
console.log('mapa declarado, todavía sin cargar');
console.log(zonas[1425]);
console.log(zonas[1000]);
